import type { ComponentType } from "react";
import * as Flags from "country-flag-icons/react/3x2";
import { Select, SelectItem, type SelectProps } from "../select/select";
import { cx } from "@/lib/cx";
import { COUNTRY_CALLING_CODES } from "./country-calling-codes";

type CountryOption = (typeof COUNTRY_CALLING_CODES)[number];
const countries = new Map<string, CountryOption>(
  COUNTRY_CALLING_CODES.map((country) => [country.code, country]),
);
const flags: Partial<Record<string, ComponentType<{ title?: string; className?: string }>>> = Flags;

function CountryFlag({ code }: { code: string }) {
  const Flag = flags[code];
  return Flag ? (
    <Flag title={code} className="h-3 w-[18px] shrink-0 overflow-hidden rounded-[2px]" />
  ) : null;
}

export interface CountryCodeSelectProps
  extends Omit<SelectProps<CountryOption>, "children" | "items" | "renderValue"> {}

/** Compact dialing-code selector, composed with the shared Select. */
export function CountryCodeSelect({
  className,
  triggerClassName,
  popoverClassName,
  defaultSelectedKey = "US",
  ...props
}: CountryCodeSelectProps) {
  return (
    <Select<CountryOption>
      aria-label="Country code"
      {...props}
      defaultSelectedKey={defaultSelectedKey}
      className={cx("shrink-0", className)}
      triggerClassName={cx("rounded-lg px-1.5 py-1", triggerClassName)}
      popoverClassName={cx("w-[220px]", popoverClassName)}
      renderValue={({ state }) => {
        const country = countries.get(String(state.selectedKey));
        return country ? (
          <>
            <CountryFlag code={country.code} />
            <span className="text-body-medium text-text-secondary">{country.callingCode}</span>
          </>
        ) : null;
      }}
    >
      {COUNTRY_CALLING_CODES.map((country) => (
        <SelectItem key={country.code} id={country.code} textValue={country.name}>
          <CountryFlag code={country.code} />
          <span className="min-w-0 flex-1 truncate text-text-primary">{country.name}</span>
          <span className="shrink-0 text-text-tertiary">{country.callingCode}</span>
        </SelectItem>
      ))}
    </Select>
  );
}

