import { CountryCodeSelect } from "./country-code-select";
import { Input, type InputProps } from "./input";

export interface PhoneInputProps extends Omit<InputProps, "leadingAddon" | "leadingIcon"> {
  /** Controlled ISO country code. */
  country?: string;
  /** Initial ISO country code for an uncontrolled selector. */
  defaultCountry?: string;
  onCountryChange?: (country: string) => void;
}

/** A text field and independent dialing-code selector. Values are never reformatted. */
export function PhoneInput({
  country,
  defaultCountry = "US",
  onCountryChange,
  isDisabled,
  ...props
}: PhoneInputProps) {
  return (
    <Input
      {...props}
      isDisabled={isDisabled}
      leadingAddon={
        <CountryCodeSelect
          selectedKey={country}
          defaultSelectedKey={defaultCountry}
          onSelectionChange={(key) => key != null && onCountryChange?.(String(key))}
          isDisabled={isDisabled}
        />
      }
    />
  );
}
